# Transform params determined from demo observation
def transform(grid_in):
    """Apply diagonal wave fill pattern to hollow square interiors"""
    grid_out = [row[:] for row in grid_in]

    # Yellow (5) squares: REMOVE completely
    for r in range(2, 7):
        for c in range(2, 10):
